import {defaults,validateConfig,files,listFiles} from './model.js';
const $ = selector => document.querySelector(selector);
const form = $('#config-form');
const storageKey = 'terra.draft.v1';
let config = {...defaults}, folder='root', kind='all', selectedFile, toastTimer;
function notify(message) { clearTimeout(toastTimer); $('#toast').textContent=message; $('#toast').hidden=false; toastTimer=setTimeout(()=>$('#toast').hidden=true,4500); }
function fillForm() { for(const [key,value] of Object.entries(config)){const field=form.elements.namedItem(key);if(typeof value==='boolean')field.checked=value;else field.value=value;} }
try { const saved=localStorage.getItem(storageKey); if(saved){config=validateConfig(JSON.parse(saved));$('#saved-label').textContent='Draf dimuat dari browser ini.';} } catch { notify('Draf tidak dapat dimuat. Nilai awal digunakan.'); }
fillForm();
function currentForm(){return validateConfig(Object.fromEntries(Object.keys(defaults).map(key=>{const field=form.elements.namedItem(key);return [key,field.type==='checkbox'?field.checked:field.value];})));}
form.addEventListener('submit',event=>{event.preventDefault();try{const next=currentForm();localStorage.setItem(storageKey,JSON.stringify(next));config=next;fillForm();$('#form-error').textContent='';$('#saved-label').textContent='Tersimpan di browser ini · belum diterapkan ke ESP32.';notify('Draf tersimpan. Perangkat belum diubah.');}catch(error){$('#form-error').textContent=error.message;}});
$('#reset').addEventListener('click',()=>{try{localStorage.removeItem(storageKey);config={...defaults};fillForm();$('#saved-label').textContent='Draf direset ke nilai awal.';$('#form-error').textContent='';notify('Draf lokal direset.');}catch{notify('Penyimpanan browser tidak tersedia.');}});
form.addEventListener('input',()=>{$('#saved-label').textContent='Ada perubahan draf yang belum disimpan.';});
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export').addEventListener('click',()=>{try{const draft=currentForm();download('terra-draft.json',JSON.stringify({schemaVersion:1,mode:'prototype',appliedToDevice:false,config:draft},null,2),'application/json');notify('Draf diekspor, belum diterapkan ke perangkat.');}catch(error){$('#form-error').textContent=error.message;}});
const titles={files:'Penyimpanan',device:'Musik & layar',settings:'Konfigurasi',proposal:'Rencana integrasi'};
function route(){const key=location.hash.slice(1);const page=Object.hasOwn(titles,key)?key:'files';for(const section of document.querySelectorAll('.page')) section.hidden=section.id!==page;for(const link of document.querySelectorAll('nav a')){if(link.dataset.page===page)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');}$('#page-label').textContent=titles[page];document.title=`${titles[page]} · Terra`;}
window.addEventListener('hashchange',()=>{route();$('#main').focus({preventScroll:true});window.scrollTo(0,0);});route();
function cell(text){const td=document.createElement('td');td.textContent=text;return td;}
function openFile(file){if(file.type==='folder'){folder=file.id;$('#search').value='';kind='all';updateFilters();renderFiles();return;}selectedFile=file;$('#dialog-title').textContent=file.name;$('#file-content').textContent=file.content;$('#file-dialog').showModal();}
function renderFiles(){
  const rows=listFiles(folder,$('#search').value,kind,$('#sort').value);const tbody=$('#file-list');tbody.replaceChildren();
  for(const file of rows){const row=document.createElement('tr');const name=cell('');const button=document.createElement('button');button.type='button';button.className='file-open';const icon=document.createElement('span');icon.className=`file-icon ${file.type==='file'?'doc':''}`;icon.setAttribute('aria-hidden','true');icon.textContent=file.type==='folder'?'▱':'TXT';const title=document.createElement('span');title.textContent=file.name;button.append(icon,title);button.addEventListener('click',()=>openFile(file));name.append(button);const bytes=file.content?new TextEncoder().encode(file.content).length:0;const action=cell('');const arrow=document.createElement('button');arrow.type='button';arrow.className='row-action';arrow.textContent=file.type==='folder'?'→':'↗';arrow.setAttribute('aria-label',`Buka ${file.name}`);arrow.addEventListener('click',()=>openFile(file));action.append(arrow);row.append(name,cell(file.type==='folder'?'Folder':'Teks'),cell(file.type==='folder'?'—':`${bytes} B`),cell(new Date(file.date+'T12:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})),action);tbody.append(row);}
  $('#empty').hidden=rows.length!==0;$('#file-count').textContent=`${rows.length} item`;const crumb=$('#breadcrumb');crumb.replaceChildren();const root=document.createElement('button');root.type='button';root.textContent='▤ Semua file';root.addEventListener('click',()=>{folder='root';$('#search').value='';kind='all';updateFilters();renderFiles();});crumb.append(root);if(folder!=='root'){const divider=document.createElement('span');divider.textContent='/';const label=document.createElement('b');label.textContent=files.find(f=>f.id===folder).name;crumb.append(divider,label);}
}
function updateFilters(){for(const button of document.querySelectorAll('[data-filter]'))button.setAttribute('aria-pressed',String(button.dataset.filter===kind));}
for(const button of document.querySelectorAll('[data-filter]'))button.addEventListener('click',()=>{kind=button.dataset.filter;updateFilters();renderFiles();});
$('#search').addEventListener('input',renderFiles);$('#sort').addEventListener('change',renderFiles);
$('#close-dialog').addEventListener('click',()=>$('#file-dialog').close());$('#download').addEventListener('click',()=>{if(selectedFile)download(selectedFile.name,selectedFile.content,'text/plain;charset=utf-8');});renderFiles();
